source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = {"up": 0, "down": 0}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 2 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            if len(cells) == 4:
                rows = sorted({y for y, x in cells})
                by_row = {y: [x for yy, x in cells if yy == y] for y in rows}
                if len(rows) == 2:
                    full = next((y for y in rows if len(by_row[y]) == 3), None)
                    stem = next((y for y in rows if len(by_row[y]) == 1), None)
                    if full is not None and stem is not None:
                        if by_row[full] == list(range(min(by_row[full]), min(by_row[full])+3)) and by_row[stem][0] == by_row[full][1]:
                            counts["up" if stem < full else "down"] += 1
    out = [[0] * 6 for _ in range(3)]
    slots = ((0, 0), (2, 0), (0, 2), (2, 2))
    for i in range(min(counts["up"], 4)):
        y, x = slots[i]
        out[y][x] = 3
    for i in range(min(counts["down"], 4)):
        y, x = slots[i]
        out[y][x+3] = 1
    return out
'''
